'use strict';

/**
 * Unit checks for the curated scene/parts library and its deterministic
 * scene composer. The data is generated by scripts/build-scene-library.py.
 */

const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const nodeTest = require('node:test');

const SceneLibrary = require('../src/server/scene-library.js');

const ROOT = path.join(__dirname, '..');
const LIBRARY = path.join(ROOT, 'data', 'library');
const INDEX_FILE = path.join(LIBRARY, 'scene-library', 'index.json');
const SCENE_FILE = path.join(LIBRARY, 'scene-library', 'scenes', 'singl-end-bicicle-cyclist-ride.json');
const HAS_BUILD = fs.existsSync(INDEX_FILE);
const test = HAS_BUILD
    ? nodeTest
    : (name, fn) => nodeTest(name, { skip: 'run: npm run build:scene-library' }, fn);
const index = HAS_BUILD ? JSON.parse(fs.readFileSync(INDEX_FILE, 'utf8')) : null;
const scene = HAS_BUILD ? JSON.parse(fs.readFileSync(SCENE_FILE, 'utf8')) : null;

function part(name) {
    const entry = index.parts.find((item) => item.name === name);
    assert.ok(entry, `part ${name} exists`);
    return entry;
}

test('the scene index describes the reviewed project and its parts', () => {
    assert.equal(index.schema, 'studio/scene-library/1');
    assert.equal(index.sceneId, 'singl-end-bicicle-cyclist-ride');
    assert.equal(index.counts.scenes, 1);
    assert.equal(index.counts.parts, 34);
    assert.equal(index.counts.buildableParts, 29);
    assert.equal(index.counts.referenceParts, 5);
    assert.equal(index.counts.groups, 11);
    assert.equal(index.counts.concepts, 16);
    assert.equal(index.counts.animatedParts, 12);
    assert.equal(index.counts.tracks, 12);
    assert.equal(index.missingVocabulary.includes('cars'), true);
    assert.equal(index.parts.filter((item) => item.buildable).length, 29);
    assert.equal(index.parts.filter((item) => !item.buildable).length, 5);
});

test('reference plates and mislabeled duplicates are not buildable', () => {
    const names = index.parts.filter((item) => !item.buildable).map((item) => item.name).sort();
    assert.deepEqual(names, [
        'bollard-middle',
        'cobblestone-sidewalk',
        'large-brick-wall',
        'large-brick-wall 3',
        'unassigned',
    ]);
    assert.equal(part('cobblestone-sidewalk').kind, 'duplicate');
    assert.equal(part('bollard-middle').kind, 'duplicate');
    assert.equal(part('large-brick-wall 3').kind, 'duplicate');
    assert.equal(part('large-brick-wall').kind, 'plate');
    assert.equal(part('unassigned').kind, 'plate');
});

test('clean source art is used and every buildable URL resolves to a file', () => {
    for (const entry of index.parts.filter((item) => item.buildable)) {
        assert.equal(entry.url.startsWith('/data/library/scene-library/assets/singl-end-bicicle-cyclist-ride/'), true, entry.name);
        const file = path.join(ROOT, entry.url.replace(/^\//, ''));
        assert.equal(fs.existsSync(file), true, `${entry.name} asset exists`);
        assert.ok(entry.box.w > 0 && entry.box.h > 0, `${entry.name} has a box`);
        assert.equal(entry.staticVisible || ['light pool on cyclist', 'scene dimmer'].includes(entry.name), true,
            `${entry.name} is visible or an effect overlay`);
    }
    const frame = part('bicycle-frame');
    assert.equal(frame.box.x, 20.66);
    assert.ok(frame.contentBox.x > 40, 'the padded export bbox is retained as evidence');
    assert.ok(frame.file.startsWith('data/projects/Singl-End-Bicicle/images/'), 'clean cropped art is preferred');
    const wall = part('large-brick-wall 2');
    assert.equal(wall.containsBakedSign, true);
    assert.equal(wall.file.endsWith('background-architecture/large-brick-wall.png'), true);
    assert.equal(part('sloped-street').derived, true);
    assert.equal(part('sloped-street').box.w, 19.13);
});

test('bicycle and cyclist parts carry the observed animation summary', () => {
    for (const name of ['bicycle-rear-wheel', 'bicycle-front-wheel', 'bicycle-frame', 'cyclist-leg', 'cyclist-torso', 'cyclist-head']) {
        const entry = part(name);
        assert.equal(entry.motion.tracked, true, `${name} is animated`);
        assert.ok(entry.motion.frames >= 200, `${name} has sampled frames`);
    }
    assert.equal(scene.animation.tracks.length, 12);
    assert.equal(scene.animation.recipes.find((recipe) => recipe.id === 'cyclist-ride').layerIds.length, 6);
});

test('building from "buildings, cars, bricks and a cyclist" reports the missing car and uses clean parts', () => {
    const build = SceneLibrary.buildScene(scene, index, 'Buildings, cars, bricks and a cyclist.');
    assert.deepEqual(build.interpretation.concepts.map((entry) => entry.id), ['buildings', 'bricks', 'cyclist']);
    assert.deepEqual(build.interpretation.missing.map((entry) => entry.id), ['cars']);
    assert.ok(build.layers.length >= 14, 'the build has a usable set');
    assert.ok(build.layers.every((layer) => layer.url), 'every layer has art');
    assert.equal(build.layers.some((layer) => /large-brick-wall|unassigned|cobblestone|bollard-middle/.test(layer.name)), false,
        'reference and duplicate plates are excluded');
    assert.ok(build.parts.some((entry) => entry.name === 'bicycle-frame'));
    assert.ok(build.parts.some((entry) => entry.name === 'cyclist-torso'));
    assert.ok(build.parts.some((entry) => entry.name === 'large-brick-wall 2'));
    assert.ok(build.animation.tracks.length >= 6);
    assert.match(build.notes.join(' '), /No car, van or other vehicle/);
    assert.equal(build.composition.width, 1098);
    assert.equal(build.composition.height, 976);
    assert.equal(build.composition.duration, 8000);
});

test('the café build deduplicates the baked wordmark and keeps the lighting tracks', () => {
    const build = SceneLibrary.buildScene(scene, index, 'A cyclist passing a brick café at night, with warm lights and bollards.');
    assert.equal(build.interpretation.missing.length, 0);
    assert.equal(build.parts.some((entry) => entry.name === 'cafe-sign'), false, 'separate sign is not layered over the baked wordmark');
    assert.ok(build.parts.some((entry) => entry.name === 'large-brick-wall 2'));
    assert.equal(build.animation.tracks.length, 12);
    assert.match(build.notes.join(' '), /baked into another selected part/);
    assert.ok(build.agent.dataQuality.length >= 5);
});

test('the workshop build uses foreground props, not the cyclist', () => {
    const build = SceneLibrary.buildScene(scene, index, 'A workshop foreground with tools and plants, street behind.');
    assert.ok(build.parts.some((entry) => entry.name === 'wooden-workbench'));
    assert.ok(build.parts.some((entry) => entry.name === 'scattered-clay-pieces'));
    assert.ok(build.parts.some((entry) => entry.name === 'mini-succulent-left'));
    assert.equal(build.parts.some((entry) => entry.name === 'bicycle-frame'), false);
    assert.ok(build.layers.some((layer) => /Brick wall|Background buildings/.test(layer.name)));
});

test('search and phrase matching stay word-aware', () => {
    assert.equal(SceneLibrary.phraseHit('scattered clay pieces', 'car'), false);
    assert.equal(SceneLibrary.phraseHit('Buildings, cars, bricks', 'car'), true);
    assert.equal(SceneLibrary.phraseHit('a cyclist passing', 'cyclist'), true);
    const bicycles = SceneLibrary.searchParts(index, { q: 'bicycle' });
    assert.ok(bicycles.parts.some((entry) => entry.name === 'bicycle-frame'));
    const groups = SceneLibrary.searchGroups(index, { q: 'cyclist' });
    assert.ok(groups.groups.some((entry) => entry.id === 'cyclist-rig'));
});

test('the scene, part and group documents can be read individually', async () => {
    const loaded = await SceneLibrary.readIndex(LIBRARY);
    assert.equal(loaded.sceneId, index.sceneId);
    const full = await SceneLibrary.readScene(LIBRARY, index.sceneId);
    assert.equal(full.parts.length, 34);
    const part = await SceneLibrary.readPart(LIBRARY, 'layer-bicycle-bicycle-frame');
    assert.equal(part.name, 'bicycle-frame');
    const group = await SceneLibrary.readGroup(LIBRARY, 'cyclist-rig');
    assert.equal(group.parts.length, 6);
    await assert.rejects(() => SceneLibrary.readScene(LIBRARY, '../index'), /Invalid scene id/);
});
